function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // protein shake
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W / 2 - 100, H / 2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // dumbbell
  ctx.fillStyle = 'gray';
  ctx.fillRect(W / 2 - 50, H / 2 - 20 - 10 * Math.sin(t), 20, 40);
  ctx.fillRect(W / 2 + 30, H / 2 - 20 - 10 * Math.sin(t), 20, 40);
  ctx.strokeRect(W / 2 - 50, H / 2 - 20 - 10 * Math.sin(t), 20, 40);
  ctx.strokeRect(W / 2 + 30, H / 2 - 20 - 10 * Math.sin(t), 20, 40);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 70);
  ctx.lineTo(W / 2, H / 2 + 100 + 10 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 100 + 10 * Math.sin(t));
  ctx.lineTo(W / 2 - 30, H / 2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 100 + 10 * Math.sin(t));
  ctx.lineTo(W / 2 + 30, H / 2 + 130);
  ctx.stroke();

  ctx.restore();
}
